import sys

def main():
    s = sys.stdin.read().split()[0]
    t = []
    for ch in s:
        if not t or t[-1] != ch:
            t.append(ch)
    n = len(t)
    f = [[0] * (n + 1) for _ in range(n + 1)]
    # f[i][j] = turns for t[i..j-1]
    for length in range(1, n + 1):
        for i in range(0, n - length + 1):
            j = i + length
            best = 1 + f[i + 1][j]
            for k in range(i + 1, j):
                if t[k] == t[i]:
                    v = f[i + 1][k] + f[k][j]
                    if v < best:
                        best = v
            f[i][j] = best
    print(f[0][n])

