import sys
from collections import deque

s = sys.stdin.read().split()[0]
n = len(s)
if n <= 7:
    letters = sorted(set(s))
    start = '.' * n
    dist = {start: 0}
    q = deque([start])
    while q:
        cur = q.popleft()
        if cur == s:
            break
        for l in range(n):
            for r in range(l, n):
                for c in letters:
                    nxt = cur[:l] + c * (r - l + 1) + cur[r + 1:]
                    if nxt not in dist:
                        dist[nxt] = dist[cur] + 1
                        q.append(nxt)
    print(dist[s])
else:
    # classic split formulation
    g = [[0] * n for _ in range(n)]
    for i in range(n):
        g[i][i] = 1
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            v = min(g[i][k] + g[k + 1][j] for k in range(i, j))
            if s[i] == s[j]:
                v -= 1
            g[i][j] = v
    print(g[0][n - 1])

